//x64 backend harness tests (commit 4b, x64-plan.md section 5).
//All machine code is generated by asmjit through Codegen_x64's assembler,
//copied into an X64Module, loaded by X64Loader (relocs applied) and run.

#include <cstdio>
#include <cstdint>
#include "harness.h"
#include "../../compiler/codegen_x64/codegen_x64.h"

using namespace asmjit;

static int tests_run=0;
static int tests_failed=0;

#define CHECK(cond) do{ \
	++tests_run; \
	if( !(cond) ){ \
		++tests_failed; \
		printf("FAIL %s:%d: %s\n",__FILE__,__LINE__,#cond); \
	} \
}while(0)

//Copy everything asmjit emitted into the module.
static void copyCode( CodeHolder &holder,X64Module &mod ){
	CodeBuffer &buf=holder.text_section()->buffer();
	mod.emitBytes( buf.data(),(int)buf.size() );
}

//Emit `call rel32` with a REL32 reloc to sym.
static void callRel32( x86::Assembler &a,X64Module &relocs,const char *sym ){
	a.db( 0xE8 );
	int at=(int)a.offset();
	a.dd( 0 );
	relocs.addReloc( sym,at,REL32 );
}

//Emit `mov rax,imm64` with an ABS64 reloc to sym. The placeholder is a large
//value so asmjit always picks the 10-byte movabs form (imm64 = last 8 bytes).
static void movAbs64( x86::Assembler &a,X64Module &relocs,const char *sym ){
	a.mov( x86::rax,Imm( (int64_t)0x1122334455667788LL ) );
	relocs.addReloc( sym,(int)a.offset()-8,ABS64 );
}

static int stub_add1( int a ){ return a+1; }

//1. mov eax,42; ret
static void test_return42(){
	CodeHolder holder;
	holder.init( Environment::host() );
	Codegen_x64 cg( &holder,false );
	x86::Assembler &a=cg.as();
	a.mov( x86::eax,42 );
	a.ret();

	X64Module mod;
	copyCode( holder,mod );
	CHECK( mod.size()>0 );

	X64Loader loader;
	std::map<std::string,void*> stubs;
	void *fn=loader.load( mod,stubs );
	CHECK( fn!=nullptr );
	if( fn ) CHECK( ((int(*)())fn)()==42 );
}

//2. ABS64: call a C stub through an absolute 64-bit address.
static void test_abs64(){
	CodeHolder holder;
	holder.init( Environment::host() );
	Codegen_x64 cg( &holder,false );
	x86::Assembler &a=cg.as();
	X64Module mod;	//relocs recorded here; code copied in afterwards

	a.sub( x86::rsp,8 );			//align stack to 16 at the call
	a.mov( x86::edi,41 );
	movAbs64( a,mod,"stub_add1" );
	a.call( x86::rax );
	a.add( x86::rsp,8 );
	a.ret();
	copyCode( holder,mod );

	X64Loader loader;
	std::map<std::string,void*> stubs;
	stubs["stub_add1"]=(void*)&stub_add1;
	void *fn=loader.load( mod,stubs );
	CHECK( fn!=nullptr );
	if( fn ) CHECK( ((int(*)())fn)()==42 );

	//Unknown symbol must fail cleanly.
	X64Loader bad;
	std::map<std::string,void*> none;
	CHECK( bad.load( mod,none )==nullptr );
}

//3. REL32: f (at offset 0) calls g in the same module.
static void test_rel32(){
	CodeHolder holder;
	holder.init( Environment::host() );
	Codegen_x64 cg( &holder,false );
	x86::Assembler &a=cg.as();
	X64Module mod;

	//f:
	a.sub( x86::rsp,8 );
	callRel32( a,mod,"g" );
	a.add( x86::rsp,8 );
	a.ret();
	int g_at=(int)a.offset();
	//g:
	a.mov( x86::eax,7 );
	a.ret();
	copyCode( holder,mod );

	//Define g at its offset (symbols are positions in the module buffer).
	X64Module linked;
	linked.emitBytes( mod.code(),g_at );
	linked.addSymbol( "g" );
	linked.emitBytes( mod.code()+g_at,mod.size()-g_at );
	for( size_t i=0;i<mod.relocs().size();++i )
		linked.addReloc( mod.relocs()[i].sym.c_str(),mod.relocs()[i].offset,mod.relocs()[i].kind );

	X64Loader loader;
	std::map<std::string,void*> stubs;
	void *fn=loader.load( linked,stubs );
	CHECK( fn!=nullptr );
	if( fn ){
		CHECK( ((int(*)())fn)()==7 );
		void *g=loader.symbol( linked,"g" );
		CHECK( g!=nullptr );
		if( g ) CHECK( ((int(*)())g)()==7 );
	}
}

int main(){
	test_return42();
	test_abs64();
	test_rel32();
	printf("test_codegen_x64: %d checks, %d failed\n",tests_run,tests_failed);
	return tests_failed?1:0;
}
